 CNativeIntrusivePointer* wrapper=(flags&1)?new CNativeIntrusivePointer:new(storage.bytes) CNativeIntrusivePointer;
 CIVCountedPointeeBase* object=references?new CIVCountedPointeeBase:0;if(object)object->IVRefCount=references;
 wrapper->Object=object;wrapperAddress=wrapper;pointeeDeletes=pointeeDestructors=wrapperFrees=0;
 void* result=wrapper->ScalarDeletingDestructor(flags);
 if(result!=wrapperAddress||wrapperFrees!=((flags&1)?1:0)||pointeeDeletes!=(references==1?1:0)||pointeeDestructors!=pointeeDeletes)return false;
 if(references>1){
  if(object->IVRefCount!=references-1)return false;
